window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-06-15"]={"date":"2026-06-15","dateKR":"2026년 6월 15일","dateEN":"15 June 2026","total":120,"sections":[{"code":"TOP","kTitle":"Section 1. Top News (10건)","eTitle":"Section 1. Top News (10 items)","type":"news","items":[{"code":"TOP-1","title":"호르무즈 위기 격화 — 美·이란 공방, 오만 앞 탱커 피격 3명 사망","src":"gCaptain","date":"2026-06-13","kSum":"호르무즈 해협 일대에서 美·이란 간 공방이 재점화되며 6월 13일 밤 정체불명 발사체가 상선 탱커를 타격했고, 오만 앞바다 탱커 피격으로 선원 3명이 사망했다. 업계는 휴전만으로 통항이 정상화되기 어렵다고 본다.","eSum":"US-Iran exchanges reignited around the Strait of Hormuz; an unidentified projectile struck a commercial tanker overnight on June 13, and tanker strikes off Oman killed three seafarers. The industry doubts a ceasefire alone will restore normal transit.","kImp":"중동 항로 리스크 프리미엄·전쟁보험료 고공행진 지속.","eImp":"Middle East route risk premiums and war-risk rates stay elevated.","url":"https://gcaptain.com/shipping-industry-says-hormuz-peace-deal-alone-wont-bring-ships-back/"},{"code":"TOP-2","title":"Posidonia 2026 개막 — 40,000명·2,227개사 참가","src":"Seatrade Maritime","date":"2026-06-01","kSum":"6월 1일 아테네에서 Posidonia 2026이 개막해 4만여 명·2,227개 전시사가 집결했다. AI·자율운항·환경기술이 전시의 중심에 섰다.","eSum":"Posidonia 2026 opened in Athens on June 1 with over 40,000 professionals and 2,227 exhibitors, with AI, autonomy and environmental tech at the centre.","kImp":"글로벌 해운 경기·기술 트렌드의 최대 지표 행사.","eImp":"The sector's bellwether event for market and technology direction.","url":"https://www.seatrade-maritime.com/event-news/posidonia-2026-takes-centre-stage-as-shipping-recalibrates-amid-global-freedom-of-navigation-challenges"},{"code":"TOP-3","title":"HD현대(HD Hyundai), HMM 발주 확정 — 18년 만 최대 컨선 수주","src":"Maritime Executive","date":"2026","kSum":"HD현대가 HMM의 컨테이너선 발주를 확정하며 18년 만 최대 수주 실적을 기록했다. HMM 총 발주는 약 28억 달러 규모다.","eSum":"HD Hyundai confirmed an HMM order, its highest containership intake in 18 years; HMM's total deal is worth about USD 2.8 billion.","kImp":"한국 해운-조선 동반 성장·친환경 선대 전환 견인.","eImp":"Drives Korean shipping-shipbuilding growth and green fleet renewal.","url":"https://maritime-executive.com/article/hd-hyundai-confirms-hmm-order-pushes-to-highest-boxship-orders-in-18-years"},{"code":"TOP-4","title":"Morning Midas, 화재 후 북태평양 침몰","src":"Seatrade Maritime","date":"2026-06","kSum":"전기차 등 차량을 싣고 화재가 발생했던 자동차운반선 Morning Midas가 심각한 화재 손상과 악천후·침수가 겹쳐 북태평양에서 침몰했다. 22명 전원은 앞서 구조됐다.","eSum":"The car carrier Morning Midas, which caught fire while carrying vehicles incl. EVs, sank in the North Pacific after severe fire damage compounded by heavy weather and water ingress; all 22 crew had been rescued.","kImp":"PCTC EV 화재 리스크 재부각 — 차량갑판 방재 강화 필요.","eImp":"Renews PCTC EV-fire risk concern; stronger car-deck fire protection needed.","url":"https://www.seatrade-maritime.com/accidents/burnt-out-morning-midas-sinks-in-north-pacific"},{"code":"TOP-5","title":"IMO MEPC 81 결의안 2026년 발효 — 탈탄소 의무 강화","src":"MarineLink","date":"2026-01","kSum":"2026년부터 강화된 EEXI·CII 요건과 암모니아·메탄올 안전 벙커링 지침이 발효됐다. CII 저등급 선박은 의무 시정조치 대상이다.","eSum":"From 2026, tightened EEXI/CII requirements and ammonia/methanol safe-bunkering guidance took effect; low-CII ships face mandatory corrective action.","kImp":"운항효율 등급이 자산가치·운항권에 직결.","eImp":"Efficiency ratings now bear on asset value and tradability.","url":"https://ports.marinelink.com/ports/port/mukilteo/news/imo-mepc-81-resolutions-kick-off-2026-driving-decarbonization-mandates"},{"code":"TOP-6","title":"2025년 해양 사이버공격 2배로 증가","src":"Maritime Executive","date":"2026","kSum":"보고서에 따르면 2025년 해양 사이버공격 발생이 2배로 늘었다. 멀웨어·DDoS 폭증과 AI 무기화가 위협 지형을 바꾸고 있다.","eSum":"A report finds maritime cyberattacks doubled in 2025, with surging malware and DDoS and the weaponization of AI reshaping the threat landscape.","kImp":"OT 보안·선박 사이버 거버넌스 투자 시급.","eImp":"Urgent need for OT security and shipboard cyber governance.","url":"https://maritime-executive.com/article/report-maritime-cyberattacks-doubled-in-2025"},{"code":"TOP-7","title":"2026, 탈탄소 경로 재정의 — '목표에서 트레이드오프로'","src":"Maritime Executive","date":"2026","kSum":"대체연료 발주 둔화 속에 2026년이 탈탄소 경로를 재정의할 전망이다. 연료 선택의 경제성·가용성 트레이드오프가 핵심 변수로 부상했다.","eSum":"With alternative-fuel ordering slowing, 2026 is set to redefine the decarbonization path as fuel economics and availability trade-offs take centre stage.","kImp":"단기엔 효율 개선이 가장 현실적 감축 수단.","eImp":"Near-term, efficiency gains are the most practical lever.","url":"https://maritime-executive.com/corporate/from-targets-to-trade-offs-why-2026-will-redefine-decarbonization-path"},{"code":"TOP-8","title":"HD현대, MSR(용융염원자로) 추진 PCTC 개념승인 획득","src":"Hellenic Shipping News","date":"2026-06-05","kSum":"HD현대 조선 계열이 6월 5일 Posidonia 2026에서 용융염원자로(MSR) 적용 대형 PCTC 개념설계에 대해 Lloyd's Register의 기본인증(AiP)을 받았다. 현대글로비스·한국원자력연구원 등이 공동 추진했다.","eSum":"HD Hyundai's shipbuilding affiliates received Approval in Principle from Lloyd's Register at Posidonia 2026 (June 5) for a large molten-salt-reactor (MSR) powered PCTC, jointly developed with Hyundai Glovis and KAERI.","kImp":"원자력 추진 상선 개념 진전 — 차세대 무탄소 선박 경쟁.","eImp":"Advances nuclear-propelled merchant concepts in the zero-carbon race.","url":"https://www.hellenicshippingnews.com/hd-hyundai-expands-smr-powerd-ships-to-car-carriers/"},{"code":"TOP-9","title":"Paris MoU 59차 위원회 글래스고 개최 (5/22)","src":"SAFETY4SEA","date":"2026-05-22","kSum":"Paris MoU가 5월 22일 글래스고에서 59차 위원회를 마쳤다. Q1 2026 억류 601건(Paris·Tokyo·USCG) 속에 ISM·화재안전 결함이 주요 과제로 지목됐다.","eSum":"The Paris MoU concluded its 59th Committee in Glasgow on May 22; amid 601 Q1 2026 detentions (Paris/Tokyo/USCG), ISM and fire-safety deficiencies remain the key concerns.","kImp":"하반기 화물고박 합동 CIC 대비 필요.","eImp":"Prepare for the H2 joint cargo-securing CIC.","url":"https://safety4sea.com/abs-port-state-control-q1-report/"},{"code":"TOP-10","title":"STCW 개정 — 폭력·괴롭힘 예방 교육 2026 발효","src":"SAFETY4SEA","date":"2026-01-01","kSum":"2026년 1월 1일부로 STCW 개정에 따라 전 선원 대상 해상 성폭력·괴롭힘 예방·대응 교육이 기본안전교육의 일부로 의무화됐다.","eSum":"From January 1, 2026, amended STCW makes prevention/response training on sexual assault and harassment a mandatory part of seafarers' basic safety training.","kImp":"승선 전 필수 교육요건 추가 — 인사·교육 체계 갱신.","eImp":"Adds a pre-boarding training requirement; update HR/training systems.","url":"https://safety4sea.com/cm-regulatory-focus-new-stcw-requirements-effective-from-2026/"}]},{"code":"ACC","kTitle":"Section 2. Accidents (해상 사고, 10건)","eTitle":"Section 2. Accidents (10 items)","type":"accident","items":[{"code":"ACC-1","title":"Golden Star 1 침몰 (인도네시아 해역, 2026-06-05)","src":"Splash 247","date":"2026-06-05","kSum":"67m·2,444 dwt 컨테이너선 Golden Star 1이 6월 5일 20시경 싱가포르 출항 후 수 시간 만에 인도네시아 해역에서 침몰했다. 사고 당시 107개 컨테이너를 적재 중이었으며, 싱가포르 해역 오염 보고는 없었다. 싱가포르 해협·말라카 해협 통항에는 영향이 없었다.","eSum":"The 67-metre, 2,444 dwt boxship Golden Star 1 departed Singapore around 20:00 on June 5 and sank in Indonesian waters hours later while carrying 107 containers. No oil pollution was reported in Singapore waters and Singapore/Malacca Strait traffic was unaffected.","kCause":"복원성 상실 또는 화물 이동 추정 (조사 진행 중).","eCause":"Suspected loss of stability or cargo shift (investigation ongoing).","kLes":"소형 피더선의 적재·복원성 관리 및 SOLAS Ch.II-1 준수 강화 필요.","eLes":"Reinforce loading/stability management and SOLAS Ch.II-1 compliance for small feeders.","url":"https://splash247.com/boxship-goes-down-off-batam/"},{"code":"ACC-2","title":"호르무즈 해협 탱커 2척 충돌·화재","src":"Seatrade Maritime","date":"2026-06","kSum":"호르무즈 해협에서 탱커 2척이 충돌해 화재가 발생했다. 지역 내 군사적 긴장이 고조된 가운데 발생한 사고로, 통항 안전 우려가 재차 부각됐다.","eSum":"Two tankers caught fire after colliding in the Strait of Hormuz, an incident occurring amid heightened regional military tension and renewing concerns over transit safety.","kCause":"혼잡·긴장 해역에서의 견시·교신 미흡 추정.","eCause":"Probable lookout/communication shortfalls in a congested, tense waterway.","kLes":"COLREG 견시 의무 및 고위험 해역 통항계획(SOLAS Ch.V) 철저 이행.","eLes":"Enforce COLREG lookout duties and high-risk passage planning (SOLAS Ch.V).","url":"https://www.seatrade-maritime.com/accidents/tankers-on-fire-after-colliding-in-straits-of-hormuz"},{"code":"ACC-3","title":"제재 대상 러 LNG선 Arctic Metagaz 화재 (몰타 인근)","src":"gCaptain","date":"2026","kSum":"제재 대상 러시아 LNG 운반선 Arctic Metagaz가 지중해 중부에서 화재 후 퇴선했다. 선원들은 리비아 SAR 구역 내 구명정에서 생존 상태로 발견됐다.","eSum":"The sanctioned Russian LNG carrier Arctic Metagaz was abandoned after a reported fire in the central Mediterranean; survivors were found alive in a lifeboat within the Libyan SAR region.","kCause":"화물·기관 구역 화재 추정 (원인 조사 중).","eCause":"Suspected cargo/engine-space fire (cause under investigation).","kLes":"가스운반선 화재 대응·퇴선 훈련 및 ISM 비상절차 점검.","eLes":"Review gas-carrier fire response, abandonment drills and ISM emergency procedures.","url":"https://gcaptain.com/crew-of-sanctioned-russian-lng-carrier-arctic-metagaz-found-alive-after-fire-incident-off-malta/"},{"code":"ACC-4","title":"OSV 화재·퇴선, 남아공 인근 선원 구조","src":"Maritime Executive","date":"2026","kSum":"남아프리카공화국 인근 해역에서 해양작업지원선(OSV)이 화재로 퇴선했고 전 선원이 구조됐다. 화재가 통제되지 않아 선박은 포기됐다.","eSum":"A burning offshore support vessel was abandoned off South Africa with all crew rescued after the fire could not be brought under control.","kCause":"기관실 화재 추정.","eCause":"Suspected engine-room fire.","kLes":"기관실 고정식 소화설비(SOLAS Ch.II-2) 및 화재 초기대응 체계 강화.","eLes":"Strengthen engine-room fixed fire-fighting (SOLAS Ch.II-2) and early response.","url":"https://maritime-executive.com/article/buring-osv-abandoned-and-crew-rescued-off-south-africa"},{"code":"ACC-5","title":"Morning Midas, 화재 후 북태평양 침몰 (차량운반선)","src":"Marine Insight","date":"2026-06","kSum":"전기차 등 차량을 싣고 화재가 발생했던 자동차운반선 Morning Midas가 심각한 화재 손상과 악천후·침수가 겹쳐 북태평양에서 침몰했다. 22명 전원은 인근 Cosco Hellas호에 구조됐다.","eSum":"The car carrier Morning Midas, which caught fire while carrying vehicles incl. EVs, sank in the North Pacific after severe fire damage compounded by heavy weather and water ingress; all 22 crew were rescued by the nearby Cosco Hellas.","kCause":"전기차(EV) 적재 갑판에서 발화한 것으로 추정.","eCause":"Fire believed to have originated on an EV-carrying deck.","kLes":"PCTC 차량갑판 화재 탐지·진압 및 EV 운송 안전지침 강화 필요.","eLes":"Enhance PCTC car-deck fire detection/suppression and EV carriage safety.","url":"https://www.seatrade-maritime.com/accidents/burnt-out-morning-midas-sinks-in-north-pacific"},{"code":"ACC-6","title":"예멘 인근 홍해 선박 피습, 선원 구조","src":"gCaptain","date":"2026","kSum":"예멘 인근 홍해에서 선박이 피습된 뒤 선원들이 구조됐다. 홍해 항로의 안보 위협이 지속되고 있음을 재확인했다.","eSum":"Crew were rescued in the Red Sea after an attack on a ship near Yemen, reaffirming persistent security threats on the Red Sea route.","kCause":"무력 공격 (드론/미사일 추정).","eCause":"Hostile attack (suspected drone/missile).","kLes":"홍해 통항 시 BMP·ISPS 보안 강화 및 회피항로 검토.","eLes":"Apply BMP/ISPS security measures and consider rerouting for Red Sea transits.","url":"https://gcaptain.com/crew-rescued-in-red-sea-after-attack-on-ship-near-yemen/"},{"code":"ACC-7","title":"인도네시아서 화물선 화재","src":"gCaptain","date":"2026","kSum":"인도네시아 해역에서 화물선에 화재가 발생했다. 동남아 해역의 잇따른 화재 사고로 화물·기관 구역 안전관리 점검 필요성이 제기됐다.","eSum":"A cargo ship caught fire in Indonesian waters, one of a series of Southeast Asian fire incidents prompting reviews of cargo and engine-space safety management.","kCause":"조사 중 (화물/기관 구역 화재 추정).","eCause":"Under investigation (suspected cargo/engine-space fire).","kLes":"열대 해역 운항 선박의 화재탐지·통풍·정비 점검 강화.","eLes":"Tighten fire-detection, ventilation and maintenance checks for tropical operations.","url":"https://gcaptain.com/cargo-ship-catches-fire-in-indonesia/"},{"code":"ACC-8","title":"필리핀 여객선 참사 — 29명 사망, 전 선대 운항정지","src":"gCaptain","date":"2026","kSum":"필리핀에서 여객선 사고로 29명이 사망하고 해당 선사 전 선대가 운항정지됐다. 도서국 연안여객 안전관리 부실이 도마에 올랐다.","eSum":"A Philippines ferry disaster claimed 29 lives and led to the grounding of the operator's entire fleet, spotlighting domestic passenger-ferry safety failures.","kCause":"복원성·과적·운항관리 문제 추정.","eCause":"Suspected stability/overloading and operational-management failures.","kLes":"연안여객선 복원성·정원관리 및 SOLAS 적용 강화 필요.","eLes":"Strengthen domestic ferry stability/passenger-count control and SOLAS application.","url":"https://gcaptain.com/philippines-ferry-disaster-claims-29-lives-as-entire-fleet-grounded/"},{"code":"ACC-9","title":"Wakashio 좌초 3년 만 조사보고서 공개 (모리셔스)","src":"gCaptain","date":"2026","kSum":"2020년 모리셔스 좌초·기름유출을 일으킨 벌크선 Wakashio의 조사보고서가 3년 만에 공개됐다. 항행계획·통신 사용 등 인적요인이 핵심 원인으로 지목됐다.","eSum":"The investigation report into the 2020 grounding and oil spill of the bulk carrier Wakashio off Mauritius was released three years on, citing human factors including passage planning and connectivity use.","kCause":"항로 이탈·견시 소홀 등 인적요인.","eCause":"Human factors — route deviation and inadequate lookout.","kLes":"항행계획 준수, 휴대기기 사용 통제 및 BRM(SOLAS Ch.V) 강화.","eLes":"Enforce passage-plan adherence, device-use control and BRM (SOLAS Ch.V).","url":"https://gcaptain.com/wakashio-report-released-3-years-after-grounding-in-mauritius/"},{"code":"ACC-10","title":"지브롤터 OS 35 충돌 조사 — 강제 도선 필요성 제기","src":"gCaptain","date":"2026","kSum":"지브롤터 OS 35 충돌 사고 조사 결과, 해당 해역의 강제 도선(mandatory pilotage) 도입 필요성이 제기됐다. 정박지 관리·통항관제 개선 권고가 포함됐다.","eSum":"The investigation into the OS 35 collision off Gibraltar revealed a critical need for mandatory pilotage, with recommendations to improve anchorage management and traffic control.","kCause":"정박지 통항관제 및 도선 부재.","eCause":"Inadequate anchorage traffic control and absence of pilotage.","kLes":"혼잡 정박지 도선·VTS 관제 강화 및 묘박 안전절차 정비.","eLes":"Strengthen pilotage/VTS control and anchoring safety procedures in congested anchorages.","url":"https://gcaptain.com/gibraltar-os-35-collision-investigation-reveals-critical-need-for-mandatory-pilotage/"}]},{"code":"PSC","kTitle":"Section 3. PSC (Port State Control, 10건)","eTitle":"Section 3. PSC (Port State Control, 10 items)","type":"news","items":[{"code":"PSC-1","title":"Paris MoU 59차 위원회 글래스고 개최 (5/22)","src":"Hellenic Shipping News","date":"2026-05-22","kSum":"Paris MoU가 5월 22일 글래스고에서 59차 위원회를 마쳤다. Q1 2026 검사에서 ISM 이행·화재안전 결함이 주요 억류 사유로 지목됐다.","eSum":"The Paris MoU concluded its 59th Committee in Glasgow on May 22; Q1 2026 inspections flagged ISM implementation and fire safety as leading detainable deficiencies.","kImp":"기본 항목(ISM·화재안전) 집중 점검 기조 지속.","eImp":"Continued focus on fundamentals — ISM and fire safety.","url":"https://safety4sea.com/abs-port-state-control-q1-report/"},{"code":"PSC-2","title":"ABS PSC 리포트 Q1 2026 — 601건 억류","src":"SAFETY4SEA","date":"2026-Q1","kSum":"2026년 1~3월 Paris MoU·Tokyo MoU·USCG 체제에서 총 601건의 선박 억류가 기록됐다. 안전관리·화재안전 준비태세가 여전히 중점 점검 대상이다.","eSum":"Between January and March 2026, 601 vessel detentions were recorded across the Paris MoU, Tokyo MoU and USCG regimes, with safety management and fire-safety readiness in focus.","kImp":"분기 억류 건수 고공행진 — 사전 자체점검 필수.","eImp":"Detentions stay elevated — proactive self-inspection essential.","url":"https://safety4sea.com/abs-psc-report-q1-2026-601-vessel-detentions-from-january-to-march/"},{"code":"PSC-3","title":"USCG, PSC 점검 중 억류 '상당 증가'","src":"Maritime Executive","date":"2026","kSum":"미국 해안경비대(USCG)가 항만국통제 점검 중 억류 건수가 상당히 증가했다고 발표했다. 미주 항만 입항 선박의 결함 관리 부담이 커지고 있다.","eSum":"The USCG reported a 'significant increase' in detentions during port state inspections, raising the deficiency-management burden for ships calling at US ports.","kImp":"미주 입항 전 결함 사전 시정 중요성 증대.","eImp":"Greater need to rectify deficiencies before US port calls.","url":"https://maritime-executive.com/article/uscg-significant-increase-in-detentions-during-port-state-inspections"},{"code":"PSC-4","title":"Paris MoU, 위조 증서 단속 강화","src":"MarineLink","date":"2026","kSum":"Paris MoU가 위조 선박 증서(fraudulent certificates) 단속에 나섰다. 증서 진위 검증 강화로 서류 부실 선박의 적발·억류가 확대될 전망이다.","eSum":"The Paris MoU is cracking down on fraudulent certificates, stepping up verification that is expected to increase detection and detention of vessels with document deficiencies.","kImp":"증서·서류 관리 부실 선박의 억류 리스크 확대.","eImp":"Higher detention risk for vessels with poor certificate/document control.","url":"https://www.marinelink.com/news/paris-mou-tackles-fraudulent-certificates-539880"},{"code":"PSC-5","title":"보고서: 예방가능 PSC 억류 증가세","src":"Maritime Executive","date":"2026","kSum":"전 선대에 걸쳐 예방 가능한 PSC 억류가 증가하고 있다는 보고가 나왔다. 기본적 정비·점검 누락이 반복 억류의 주원인으로 지목됐다.","eSum":"A report finds preventable PSC detentions are increasing across the fleet, with lapses in basic maintenance and checks cited as the main driver of repeat detentions.","kImp":"기초 정비·점검 강화로 억류의 상당수 예방 가능.","eImp":"Many detentions are avoidable through stronger basic maintenance.","url":"https://maritime-executive.com/article/report-preventable-psc-detentions-are-increasing-across-the-fleet"},{"code":"PSC-6","title":"AI 플랫폼, 글로벌 164건 PSC 억류 추적","src":"Marine Insight","date":"2026","kSum":"신규 AI 플랫폼이 연초 이후 전 세계 164건의 PSC 억류를 실시간 인텔리전스로 전환해 추적한다. 선주의 사전 리스크 진단을 지원한다.","eSum":"A new AI platform tracks 164 global PSC detentions since the start of the year, transforming the data into real-time intelligence to support owners' proactive risk assessment.","kImp":"데이터 기반 사전 점검이 PSC 대응의 표준으로.","eImp":"Data-driven pre-screening becoming standard for PSC readiness.","url":"https://www.marineinsight.com/shipping-news/new-ai-platform-tracks-164-global-psc-detentions-transforms-port-state-control-data-into-real-time-intelligence/"},{"code":"PSC-7","title":"International Registries, PSC 억류 트렌드 분석","src":"Hellenic Shipping News","date":"2026","kSum":"International Registries(마셜제도 선적)가 PSC 억류 추세 분석을 공개했다. 기국 차원의 사전 점검·선주 지원 프로그램 확대가 강조됐다.","eSum":"International Registries (Marshall Islands registry) published an analysis of PSC detention trends, emphasizing expanded flag-state pre-screening and owner support programs.","kImp":"기국-선주 협력형 결함 예방 모델 부상.","eImp":"Flag-owner cooperative deficiency-prevention model gaining traction.","url":"https://www.hellenicshippingnews.com/international-registries-port-state-control-detention-trends/"},{"code":"PSC-8","title":"Paris·Tokyo MoU, 화물고박 합동 CIC 예고 (9~11월)","src":"SAFETY4SEA","date":"2026","kSum":"Paris MoU와 Tokyo MoU가 2026년 9월 1일~11월 30일 화물 고박(cargo securing)을 주제로 합동 집중점검캠페인(CIC)을 시행한다. Paris MoU 억류율은 2025년 4.18%로 상승했다.","eSum":"The Paris and Tokyo MoUs will run a joint Concentrated Inspection Campaign on cargo securing from Sep 1 to Nov 30, 2026; the Paris MoU detention rate rose to 4.18% in 2025.","kImp":"하반기 화물 고박 결함 집중 점검 대비 필요.","eImp":"Prepare for H2 focus on cargo-securing deficiencies.","url":"https://safety4sea.com/abs-psc-report-q1-2026-601-vessel-detentions-from-january-to-march/"},{"code":"PSC-9","title":"PSC 억류는 대개 준비 실패 — 사전 점검 중요성","src":"SAFETY4SEA","date":"2026","kSum":"SAFETY4SEA는 PSC 억류 대부분이 준비 실패에서 비롯된다고 지적했다. 선원의 비상장비 친숙도와 SMS 기록 정비가 핵심 예방책이다.","eSum":"SAFETY4SEA notes most PSC detentions stem from preparation failures, with crew familiarity with emergency equipment and well-kept SMS records as key prevention.","kImp":"사전 자체점검·훈련이 억류 예방의 출발점.","eImp":"Self-inspection and drills are the starting point for avoiding detention.","url":"https://safety4sea.com/cm-psc-detentions-are-usually-a-preparation-failure/"},{"code":"PSC-10","title":"ICS, 신설 IMO 'Carriage Ban' 억류 가능성 경고","src":"gCaptain","date":"2026","kSum":"ICS는 신설 IMO 'Carriage Ban'에 따라 비적합 선박이 억류될 수 있다고 경고했다. PSC와 연계된 규제 강화로 컴플라이언스 부담이 커지고 있다.","eSum":"The ICS warned that ships could face detention under a new IMO 'Carriage Ban', with PSC-linked regulatory tightening adding to the compliance burden.","kImp":"규제-PSC 연계 강화로 선제적 컴플라이언스 필수.","eImp":"Regulation-PSC linkage makes proactive compliance essential.","url":"https://gcaptain.com/ics-ships-could-face-detention-under-new-imo-carriage-ban/"}]},{"code":"PCTC","kTitle":"Section 4. PCTC / Car Carrier (10건)","eTitle":"Section 4. PCTC / Car Carrier (10 items)","type":"news","items":[{"code":"PCTC-1","title":"PCTC 신조 MV Ocean Explorer 인도","src":"MarineLink","date":"2026","kSum":"신형 PCTC인 MV Ocean Explorer가 인도됐다. 대형 자동차운반선 선대 확충이 이어지며 차량 해상물류 공급능력이 확대되고 있다.","eSum":"The new PCTC MV Ocean Explorer was delivered, continuing the build-up of large car-carrier capacity and expanding seaborne vehicle logistics supply.","kImp":"PCTC 선복 증가로 자동차 물류 병목 완화 기대.","eImp":"Rising PCTC capacity may ease vehicle-logistics bottlenecks.","url":"https://www.marinelink.com/news/pctc-vessel-mv-ocean-explorer-delivered-534161"},{"code":"PCTC-2","title":"Wallenius Wilhelmsen, 이중연료 자동차선 4척 추가 발주","src":"MarineLink","date":"2026","kSum":"Wallenius Wilhelmsen이 9,300 CEU급 메탄올 이중연료 PCTC 4척을 추가 발주했다. MAN B&W 7S60ME-C10.5-LGIM 엔진을 탑재하며 진링조선소에서 2026년 중반부터 인도된다.","eSum":"Wallenius Wilhelmsen ordered four more 9,300 CEU methanol dual-fuel PCTCs with MAN B&W 7S60ME-C10.5-LGIM engines, to be built at Jinling and delivered from mid-2026.","kImp":"메탄올 추진 PCTC 확산으로 친환경 차량운송 가속.","eImp":"Spreads methanol-fuelled PCTCs, accelerating greener vehicle transport.","url":"https://www.marinelink.com/news/wallenius-wilhelmsen-orders-four-dualfuel-511830"},{"code":"PCTC-3","title":"MacGregor, PCTC 2척용 RoRo 설비 대형 수주","src":"Maritime Executive","date":"2026","kSum":"MacGregor가 PCTC 2척을 위한 RoRo 하역설비 대형 수주를 확보했다. 친환경 자동차선의 갑판·램프 시스템 고도화가 이어지고 있다.","eSum":"MacGregor secured a significant RoRo equipment order for two PCTC vessels, continuing the upgrade of deck and ramp systems for greener car carriers.","kImp":"친환경 PCTC 기자재 공급망 성장.","eImp":"Growth in the green-PCTC equipment supply chain.","url":"https://maritime-executive.com/corporate/macgregor-received-a-significant-roro-equipment-order-for-two-pctc-vessels"},{"code":"PCTC-4","title":"세계 최대 PCTC Höegh Aurora — 9,100 CEU·EV 대응","src":"SAFETY4SEA","date":"2026","kSum":"세계 최대 PCTC인 Höegh Aurora는 14개 갑판에 최대 9,100 CEU를 적재하며 전 갑판에서 전기차(EV) 운송이 가능하도록 설계됐다. 강화 갑판·램프로 EV 하중에 대응한다.","eSum":"The world's largest PCTC, Höegh Aurora, features 14 decks for up to 9,100 CEU and is designed to carry EVs on all decks with reinforced decks and ramps.","kImp":"EV 대응형 메가 PCTC가 차량운송 표준으로 부상.","eImp":"EV-capable mega-PCTCs becoming the vehicle-transport benchmark.","url":"https://safety4sea.com/do-you-know-the-differences-between-pctcs-and-roro-ropax/"},{"code":"PCTC-5","title":"Sallaum Lines, LNG 이중연료 자동차선 2척 인도","src":"MarineLink","date":"2026","kSum":"Sallaum Lines가 LNG 이중연료 PCTC인 MV Ocean Express·MV Ocean Navigator 2척을 인도받았다. 신흥 선사의 친환경 PCTC 진입이 확대되고 있다.","eSum":"Sallaum Lines took delivery of two LNG dual-fuel PCTCs, the MV Ocean Express and MV Ocean Navigator, marking growing entry of emerging carriers into green PCTCs.","kImp":"LNG 이중연료 PCTC 채택 저변 확대.","eImp":"Broadening adoption of LNG dual-fuel PCTCs.","url":"https://www.marinelink.com/news/sallaum-takes-delivery-lng-dualfueled-car-540038"},{"code":"PCTC-6","title":"Seaspan, LNG 자동차선 최대 10척 발주 — 신시장 진출","src":"gCaptain","date":"2026","kSum":"Seaspan이 중국 상하이 와이가오차오조선에 LNG 이중연료 PCTC 6척(옵션 4척 포함 최대 10척)을 발주하며 자동차선 시장에 진출했다. 메탄올·암모니아 전환 대응 설계를 적용했다.","eSum":"Seaspan ordered up to ten LNG dual-fuel PCTCs (six firm plus four options) at Shanghai Waigaoqiao, entering the car-carrier market with designs ready for methanol/ammonia conversion.","kImp":"리스선사의 진입으로 PCTC 공급경쟁 심화.","eImp":"Lessor entry intensifies PCTC supply competition.","url":"https://gcaptain.com/seaspan-orders-up-to-ten-lng-fueled-car-carriers-expanding-into-new-market/"},{"code":"PCTC-7","title":"China Merchants, 메탄올 자동차선으로 발주 붐 가세","src":"Maritime Executive","date":"2026","kSum":"China Merchants가 메탄올 추진 자동차선을 추가 발주하며 PCTC 발주 붐에 가세했다. 중국 선사·조선의 친환경 자동차선 공급이 빠르게 늘고 있다.","eSum":"China Merchants added methanol-fuelled car carriers to the ordering boom, with Chinese owners and yards rapidly expanding green car-carrier supply.","kImp":"중국발 공급 증가로 글로벌 PCTC 선복 재편.","eImp":"China-led supply growth reshapes global PCTC capacity.","url":"https://maritime-executive.com/article/china-merchants-adds-to-car-carrier-boom-with-methanol-fueled-ships"},{"code":"PCTC-8","title":"中, HMM-현대글로비스 협력 최대 자동차선 진수","src":"Maritime Executive","date":"2026","kSum":"중국 조선소가 HMM-현대글로비스(Hyundai Glovis) 협력 사업의 최대 규모 자동차운반선을 진수했다. 한국 선사 주도 친환경 PCTC 선대 확충이 진행되고 있다.","eSum":"A Chinese yard launched the largest car carrier for the HMM-Hyundai Glovis partnership, advancing Korean-led green PCTC fleet expansion.","kImp":"한·중 협력형 PCTC 확충으로 차량운송 경쟁력 강화.","eImp":"Korea-China PCTC build-up strengthens vehicle-transport competitiveness.","url":"https://maritime-executive.com/article/china-launches-largest-car-carrier-for-hmm-hyundai-glovis-partnership"},{"code":"PCTC-9","title":"Höegh Aurora, 세계 최대 PCTC 첫 항해 — 12척 시리즈","src":"MarineLink","date":"2026","kSum":"세계 최대 PCTC인 Höegh Aurora(9,100 CEU)가 첫 항해에 나섰다. China Merchant Heavy Industries 건조 Aurora급 12척 중 첫 선박으로 EV 전 갑판 운송이 가능하다.","eSum":"The world's largest PCTC, Höegh Aurora (9,100 CEU), set off on its maiden voyage — the first of a 12-ship Aurora class from China Merchant Heavy Industries, able to carry EVs on all decks.","kImp":"EV 대응 메가 PCTC가 차량운송 표준으로 부상.","eImp":"EV-capable mega-PCTCs become the benchmark.","url":"https://www.marinelink.com/news/worlds-largest-car-carrier-hegh-aurora-515648"},{"code":"PCTC-10","title":"불확실성에 대체연료 선박 발주 둔화","src":"Maritime Executive","date":"2026","kSum":"연료 선택 불확실성과 다양한 접근으로 대체연료 선박(자동차선 포함) 발주가 둔화되고 있다. 선주들이 메탄올·암모니아·LNG 사이에서 관망세를 보인다.","eSum":"Uncertainty and a diverse approach are slowing orders for alternative-fuel vessels, including car carriers, as owners weigh methanol, ammonia and LNG.","kImp":"연료 표준 불확실성이 PCTC 발주 결정 지연 요인.","eImp":"Fuel-standard uncertainty is delaying PCTC ordering decisions.","url":"https://maritime-executive.com/article/uncertainty-and-diverse-approach-slow-orders-for-alternative-fuel-vessels"}]},{"code":"WW","kTitle":"Section 5. Wallenius Wilhelmsen (10건)","eTitle":"Section 5. Wallenius Wilhelmsen (10 items)","type":"news","items":[{"code":"WW-1","title":"Wallenius Wilhelmsen, 5.8억 달러 다년 운송계약 확보","src":"MarineLink","date":"2026","kSum":"Wallenius Wilhelmsen이 약 5.8억 달러 규모 다년 해상운송 계약을 따냈다. 견조한 자동차 물동량 속 장기계약 기반을 강화했다.","eSum":"Wallenius Wilhelmsen landed a multi-year shipping contract worth about US$580m, reinforcing its long-term contract base amid solid vehicle volumes.","kImp":"장기계약 확대로 실적 가시성 제고.","eImp":"More long-term contracts improve earnings visibility.","url":"https://www.marinelink.com/news/wallenius-wilhelmsen-lands-m-multiyear-519075"},{"code":"WW-2","title":"Wallenius Wilhelmsen, 1.3억 달러 아시아 운송계약 추가","src":"Splash 247","date":"2026","kSum":"Wallenius Wilhelmsen이 1.3억 달러 규모 아시아발 운송계약을 추가했다. 아시아발 강세 운임이 수익을 뒷받침한다.","eSum":"Wallenius Wilhelmsen added a US$130m Asian shipping contract, with strong ex-Asia rates underpinning earnings.","kImp":"아시아발 계약 확대 — 시황 강세 활용.","eImp":"More Asian contracts capitalise on firm rates.","url":"https://splash247.com/wallenius-wilhelmsen-adds-130m-asian-shipping-contract/"},{"code":"WW-3","title":"WW, USTR 수수료 유지 전망 — 비용 부담 지속","src":"Lloyd's List","date":"2026","kSum":"Wallenius Wilhelmsen은 일시 유예 발표에도 USTR 수수료가 유지될 것으로 보고 있다. 2026년 전체 3~4억 달러 비용 노출이 예상된다.","eSum":"Wallenius Wilhelmsen expects USTR fees to remain despite the suspension announcement, anticipating US$300-400m cost exposure for full-year 2026.","kImp":"美 항만 수수료가 수익성의 주요 변수.","eImp":"US port fees are a key swing factor for profitability.","url":"https://www.lloydslist.com/LL1155385/Wallenius-Wilhelmsen-expects-USTR-fees-to-remain-despite-suspension-announcement"},{"code":"WW-4","title":"WW, 진링조선소에 PCTC 최대 12척 발주","src":"Seatrade Maritime","date":"2026","kSum":"Wallenius Wilhelmsen이 중국 진링조선소(Jinling)에 9,300 CEU급 메탄올 이중연료 PCTC를 최대 12척 발주했다. 2026년 중반부터 인도된다.","eSum":"Wallenius Wilhelmsen ordered up to 12 methanol dual-fuel 9,300 CEU PCTCs from Jinling Shipyard, with deliveries from mid-2026.","kImp":"메가 메탄올 PCTC로 선대 현대화 가속.","eImp":"Mega methanol PCTCs accelerate fleet modernisation.","url":"https://www.seatrade-maritime.com/newbuilding/wallenius-wilhelmsen-ordering-12-pctcs-jinling-shipyard"},{"code":"WW-5","title":"WW, PCTC 30년 생존연한까지 운용","src":"Seatrade Maritime","date":"2026","kSum":"강한 수요 속에 Wallenius Wilhelmsen이 기존 PCTC를 30년 특별검사까지 운용하기로 했다. 노후선 운용으로 선복을 확보한다.","eSum":"Amid strong demand, Wallenius Wilhelmsen will run PCTCs through their 30-year survey, using older tonnage to secure capacity.","kImp":"강세 시황에서 선복 확보 우선.","eImp":"Prioritises capacity in a strong market.","url":"https://www.seatrade-maritime.com/cargo/shipping-buoys-wallenius-wilhelmsen-in-volatile-market"},{"code":"WW-6","title":"WW, 호주 물류 계약 체결","src":"MarineLink","date":"2026","kSum":"Wallenius Wilhelmsen이 호주에서 물류 계약을 체결하며 통합 물류망을 확장했다. 해상-내륙 일관 서비스 역량을 강화한다.","eSum":"Wallenius Wilhelmsen inked a logistics contract in Australia, expanding its integrated network and end-to-end service capability.","kImp":"물류 영역 확장으로 가치사슬 장악력 제고.","eImp":"Logistics expansion deepens value-chain control.","url":"https://www.marinelink.com/news/wallenius-wilhelmsen-inks-logistics-529652"},{"code":"WW-7","title":"WW, 브런즈윅(美) 터미널 개장","src":"MarineLink","date":"2026","kSum":"Wallenius Wilhelmsen이 美 남대서양 허브인 브런즈윅 터미널(차량처리센터 포함)을 개장했다. 조지아 항만청과 최장 30년 임대 계약을 맺었다.","eSum":"Wallenius Wilhelmsen opened its Brunswick (US) South Atlantic hub terminal with processing centres, under a lease with the Georgia Ports Authority of up to 30 years.","kImp":"美 자동차 물류 거점 확보.","eImp":"Secures a US vehicle-logistics hub.","url":"https://www.marinelink.com/news/wallenius-wilhelmsen-opens-brunswick-521414"},{"code":"WW-8","title":"WW 2026 선복·물동량 약 90% 확보","src":"gCaptain","date":"2026","kSum":"Wallenius Wilhelmsen은 2026년 선복·물동량의 약 90%를 이미 확보했다. 높은 계약 커버리지로 실적 안정성을 확보했다.","eSum":"Wallenius Wilhelmsen has already covered about 90% of its 2026 capacity and volumes, giving strong earnings stability.","kImp":"높은 커버리지로 시황 변동 방어.","eImp":"High coverage buffers market volatility.","url":"https://gcaptain.com/auto-transport-company-wallenius-wilhelmsen-reports-record-quarterly-earnings/"},{"code":"WW-9","title":"Equinor, WW에 바이오메탄올 공급","src":"MarineLink","date":"2026","kSum":"Equinor가 2026년 말부터 Wallenius Wilhelmsen에 바이오메탄올을 공급한다. 제브뤼헤·안트베르펜에서 신규 메탄올 이중연료선에 사용된다.","eSum":"Equinor will supply bio-methanol to Wallenius Wilhelmsen from late 2026 for new dual-fuel methanol vessels at Zeebrugge and Antwerp.","kImp":"연료 공급계약으로 메탄올 추진 실행력 제고.","eImp":"Secured fuel supply boosts methanol-propulsion execution.","url":"https://www.marinelink.com/news/equinor-supply-biomethanol-wallenius-536826"},{"code":"WW-10","title":"Svitzer·WW, EcoTow 협약 — Scope 3 감축","src":"MarineLink","date":"2026","kSum":"Wallenius Wilhelmsen이 Svitzer와 글로벌 EcoTow 협약을 체결해 호주·영국·스칸디나비아 예선 작업의 Scope 3 배출 감축을 추진한다.","eSum":"Wallenius Wilhelmsen signed a global EcoTow agreement with Svitzer to cut Scope 3 emissions from tug jobs in Australia, the UK and Scandinavia.","kImp":"공급망(Scope 3) 배출까지 감축 확대.","eImp":"Extends emissions cuts into the supply chain (Scope 3).","url":"https://www.marinelink.com/news/svitzer-wallenius-wilhelmsen-sign-ecotow-524651"}]},{"code":"EE","kTitle":"Section 6. Energy Efficiency (10건)","eTitle":"Section 6. Energy Efficiency (10 items)","type":"news","items":[{"code":"EE-1","title":"IMO MEPC 81, 2026년 탈탄소 의무 본격화","src":"MarineLink","date":"2026-01","kSum":"강화된 EEXI·CII와 암모니아·메탄올 안전 벙커링 지침이 2026년 발효됐다. CII D·E 2년 연속 선박은 의무 시정조치 대상이다.","eSum":"Tightened EEXI/CII and ammonia/methanol safe-bunkering guidance took effect in 2026; ships rated D/E for two years face mandatory corrective action.","kImp":"운항효율 등급 관리가 자산가치와 직결.","eImp":"Efficiency ratings directly affect asset value.","url":"https://ports.marinelink.com/ports/port/mukilteo/news/imo-mepc-81-resolutions-kick-off-2026-driving-decarbonization-mandates"},{"code":"EE-2","title":"메탄올·암모니아·LNG? 미래연료 경제성 논쟁","src":"Splash 247","date":"2026","kSum":"Splash가 메탄올·암모니아·LNG의 경제성을 비교 분석했다. 가격·가용성·규제 불확실성이 선주의 연료 선택을 좌우하고 있다.","eSum":"Splash analysed the economics behind methanol, ammonia and LNG, with price, availability and regulatory uncertainty driving owners' fuel choices.","kImp":"연료 경제성 비교가 발주 의사결정의 핵심.","eImp":"Fuel economics comparisons are central to ordering decisions.","url":"https://splash247.com/methanol-ammonia-or-lng-the-economics-behind-future-fuels-in-shipping/"},{"code":"EE-3","title":"2026, '암모니아·메탄올의 해' 아니다 — 대체연료 발주 급감","src":"Maritime Executive","date":"2026","kSum":"업계 전망은 예상보다 신중하다. 대체연료 신조 발주가 급감하고 대규모 이중연료 채택 확신이 약화됐으며, DNV는 효율 개선이 유일한 대규모 검증 경로라고 본다.","eSum":"The 2026 outlook is more cautious: alternative-fuel newbuild orders fell sharply and confidence in large-scale dual-fuel uptake is waning; DNV sees efficiency as the only proven large-scale path.","kImp":"효율 개선이 단기 탈탄소의 핵심 수단.","eImp":"Efficiency is the key near-term decarbonization lever.","url":"https://maritime-executive.com/corporate/from-targets-to-trade-offs-why-2026-will-redefine-decarbonization-path"},{"code":"EE-4","title":"싱가포르 MPA, 암모니아 벙커링 시범설비 개소","src":"Maritime Executive","date":"2026","kSum":"싱가포르 해사항만청(MPA)이 암모니아 벙커링 시범설비를 개소하며 대체연료 인프라 구축에 진전을 이뤘다. 안전 운영 절차 실증이 핵심이다.","eSum":"The Maritime and Port Authority of Singapore inaugurated an ammonia bunkering pilot facility, advancing alternative-fuel infrastructure with a focus on safe operating procedures.","kImp":"암모니아 벙커링 인프라 실증 — 공급망 형성 신호.","eImp":"Ammonia bunkering pilot signals supply-chain formation.","url":"https://maritime-executive.com/corporate/from-targets-to-trade-offs-why-2026-will-redefine-decarbonization-path"},{"code":"EE-5","title":"Oceanbird 윙세일, 실증 시연서 최대 높이 도달","src":"Maritime Executive","date":"2026","kSum":"풍력보조 추진 Oceanbird 윙세일이 실증 시연에서 최대 높이까지 전개에 성공했다. 자동차운반선 등에 적용될 풍력보조 기술이 진전됐다.","eSum":"The Oceanbird wing sail reached full height in a demonstration, advancing wind-assisted propulsion intended for car carriers and other ships.","kImp":"풍력보조 추진 상용화 단계 진입.","eImp":"Wind-assist propulsion moves toward commercialisation.","url":"https://maritime-executive.com/article/oceanbird-wing-sail-reaches-for-the-sky-in-demonstration"},{"code":"EE-6","title":"넷제로 항해 — 탈탄소 의무와 그린연료 경쟁","src":"MarineLink","date":"2026","kSum":"탈탄소 의무 강화로 그린연료 확보 경쟁이 가열되고 있다. 메탄올·암모니아·바이오연료 공급망 구축이 선사 경쟁력의 관건이다.","eSum":"Tightening mandates are intensifying the green-fuels race, making methanol, ammonia and biofuel supply chains central to competitiveness.","kImp":"연료 공급망 선점이 경쟁우위 좌우.","eImp":"Securing fuel supply chains decides advantage.","url":"https://www.marinelink.com/articles/maritime/sailing-to-netzero-the-decarbonization-mandate-and-the-green-103810"},{"code":"EE-7","title":"세계 최초 풍력·수소 무배출 화물선 추진","src":"Maritime Executive","date":"2026","kSum":"풍력과 수소를 결합한 세계 최초 무배출 화물선 프로젝트가 추진된다. 대형 로터세일과 수소 내연기관을 결합한 개념이 대표적이다.","eSum":"A world-first zero-emission cargo ship combining wind and hydrogen is advancing, exemplified by a concept pairing large rotor sails with a hydrogen engine.","kImp":"풍력+수소 하이브리드가 무배출 선박의 한 축.","eImp":"Wind-plus-hydrogen hybrids form one zero-emission path.","url":"https://maritime-executive.com/article/world-s-first-zero-emission-wind-and-hydrogen-power-cargo-ship"},{"code":"EE-8","title":"Fincantieri, 세계 최초 수소 크루즈선 Viking Libra 진수","src":"Maritime Executive","date":"2026-03","kSum":"Fincantieri가 2026년 3월 세계 최초 수소 추진 크루즈선으로 홍보되는 Viking Libra(54,300 GT)를 진수했다. 액화수소·연료전지 추진을 적용한다.","eSum":"In March 2026 Fincantieri floated the Viking Libra (54,300 GT), billed as the world's first hydrogen-powered cruise ship, using liquefied hydrogen and fuel cells.","kImp":"여객 부문 수소 추진 상용화 신호탄.","eImp":"A milestone for hydrogen propulsion in passenger ships.","url":"https://maritime-executive.com/article/fincantieri-floats-for-viking-first-hydrogen-powered-cruise-ship"},{"code":"EE-9","title":"DNV: LNG 추진 컨선이 대체연료 발주 견인","src":"MarineLink","date":"2026","kSum":"DNV에 따르면 LNG 추진 컨테이너선이 대체연료 발주를 떠받쳤다. LNG가 단기 전환연료로서 핵심 역할을 유지하고 있다.","eSum":"Per DNV, LNG-fuelled container ships propped up alternative-fuel orders, with LNG retaining a key near-term transition role.","kImp":"LNG가 중기 전환연료 입지 유지.","eImp":"LNG keeps its medium-term transition role.","url":"https://www.marinelink.com/news/lngfueled-container-ships-prop-534268"},{"code":"EE-10","title":"MOL, 수소·바이오연료 배터리 하이브리드선 진수","src":"Maritime Executive","date":"2026","kSum":"MOL이 수소·바이오연료로 구동되는 배터리 하이브리드 선박을 진수했다. 다중 청정연료·배터리 조합으로 연안 배출을 저감한다.","eSum":"MOL launched a battery-hybrid vessel powered by hydrogen and biofuel, combining multiple clean fuels with batteries to cut coastal emissions.","kImp":"다중연료·배터리 하이브리드 실증 확대.","eImp":"Expands testing of multi-fuel battery hybrids.","url":"https://maritime-executive.com/article/mol-launches-battery-hybrid-vessel-powered-by-hydrogen-and-biofuel"}]},{"code":"DIG","kTitle":"Section 7. Digitalization (10건)","eTitle":"Section 7. Digitalization (10 items)","type":"news","items":[{"code":"DIG-1","title":"2025년 해양 사이버공격 2배 — 멀웨어·DDoS 폭증","src":"Maritime Executive","date":"2026","kSum":"보고서에 따르면 2025년 해양 사이버공격이 2배로 늘었다. 멀웨어·분산서비스거부(DDoS) 급증과 적대적 AI가 위협을 키우고 있다.","eSum":"A report finds maritime cyberattacks doubled in 2025, driven by an explosion of malware and DDoS and the rise of adversarial AI.","kImp":"사이버 회복력 투자가 운영 연속성의 전제.","eImp":"Cyber resilience investment underpins operational continuity.","url":"https://maritime-executive.com/article/report-maritime-cyberattacks-doubled-in-2025"},{"code":"DIG-2","title":"해양 사이버리스크 '제3시대' 진입","src":"MarineLink","date":"2026","kSum":"IT-OT 융합으로 선박이 사실상 '떠다니는 데이터센터'가 되며 사이버 공격 표면이 급확대됐다. 적대적 AI 무기화가 핵심 위협으로 부상했다.","eSum":"IT/OT convergence has turned ships into floating data centres, sharply widening the attack surface, with weaponized adversarial AI emerging as a core threat.","kImp":"OT 보안·선박 사이버 거버넌스 시급.","eImp":"Urgent OT security and shipboard cyber governance.","url":"https://www.marinelink.com/news/navigating-third-era-maritime-cyber-risk-536724"},{"code":"DIG-3","title":"Posidonia 2026, AI 인프라·자율선 신규 이니셔티브 출범","src":"SAFETY4SEA","date":"2026","kSum":"Posidonia 2026에서 Lloyd's Register 주도로 부유식 데이터센터·차세대 선형설계·디지털 보증 프레임워크 등 AI 인프라와 자율선 이니셔티브가 발표됐다.","eSum":"At Posidonia 2026, Lloyd's Register-led initiatives launched spanning floating data centres, advanced vessel designs and digital-assurance frameworks for AI infrastructure and autonomy.","kImp":"해운, AI 디지털 인프라 영역으로 확장.","eImp":"Shipping expands into AI digital infrastructure.","url":"https://safety4sea.com/new-initiatives-formed-to-advance-ai-infrastructure-and-autonomous-vessel-design/"},{"code":"DIG-4","title":"AI 기술, 해운 사이버공격 위험 키운다 — 신규 데이터","src":"Marine Insight","date":"2026","kSum":"신규 데이터에 따르면 조직의 87%가 AI 관련 취약성을 가장 빠르게 증가하는 위험으로 인식한다. AI 도입이 사이버 책임 정의보다 빠르게 진행되고 있다.","eSum":"New data shows 87% of organizations view AI-related vulnerabilities as the fastest-growing risk, with AI adoption outpacing the definition of cyber accountability.","kImp":"AI 도입 속도-보안 거버넌스 격차 해소 필요.","eImp":"Close the AI-adoption vs governance gap.","url":"https://www.marineinsight.com/shipping-news/ai-technology-is-placing-the-maritime-industry-at-greater-risk-of-a-cyber-attack-reveals-new-data/"},{"code":"DIG-5","title":"디지털화에서 자동화로 — 2026년 운영 재편","src":"Maritime Executive","date":"2026","kSum":"AI가 생성형에서 에이전트형·물리형으로 진화하며 자율운항·최적 선대운영으로 확장하고 있다. 선박-육상 상호운용성이 핵심 화두다.","eSum":"As AI evolves from generative to agentic and physical, it is expanding into autonomous navigation and optimal fleet operations, with ship-shore interoperability key.","kImp":"AI 진화가 운영 자동화 범위를 급확대.","eImp":"AI's evolution rapidly widens operational automation.","url":"https://maritime-executive.com/editorials/from-digitalization-to-automation-2026-will-redefine-maritime-operations"},{"code":"DIG-6","title":"AI·사이버보안과 해상운송시스템","src":"Maritime Executive","date":"2026","kSum":"AI와 자율 시스템 도입으로 디지털 공급망을 겨냥한 표적 공격 위험이 커졌다. 데이터 융합 사이버 회복력 접근이 요구된다.","eSum":"AI and autonomous systems raise the risk of targeted attacks on the digital supply chain, demanding a data-fusion cyber-resilience approach.","kImp":"센서 융합 단계 넘어 물리기반 정합성 검증 필요.","eImp":"Move beyond sensor fusion to physics-based consistency checks.","url":"https://maritime-executive.com/editorials/ai-cybersecurity-and-the-maritime-transport-system"},{"code":"DIG-7","title":"자율운항, 사이버보안이 최대 우려로 지속","src":"Maritime Executive","date":"2026","kSum":"자율운항선 도입에서 사이버보안이 가장 큰 우려로 지속되고 있다. 원격제어센터·소프트웨어 무결성 검증이 핵심 과제다.","eSum":"Cybersecurity remains the leading concern for autonomous shipping, with remote-control centres and software-integrity assurance as key challenges.","kImp":"자율운항 신뢰성의 전제는 사이버 회복력.","eImp":"Cyber resilience is the precondition for autonomy.","url":"https://maritime-executive.com/editorials/cybersecurity-risk-remains-the-leading-concern-for-autonomous-shipping"},{"code":"DIG-8","title":"IMO, 종합 디지털 전략 수립 추진","src":"MarineLink","date":"2026","kSum":"IMO가 해운 디지털화를 위한 종합 디지털 전략 수립에 착수했다. e-navigation·데이터 표준·상호운용성 정립이 목표다.","eSum":"The IMO moved to develop a comprehensive digital strategy for shipping, targeting e-navigation, data standards and interoperability.","kImp":"국제 디지털 표준화로 데이터 연계 가속.","eImp":"International digital standardisation speeds data integration.","url":"https://www.marinelink.com/news/imo-develop-comprehensive-digital-523645"},{"code":"DIG-9","title":"IMO, MASS 코드 채택 — 자율운항 규제 현실화","src":"gCaptain","date":"2026","kSum":"IMO가 MASS 코드를 채택하며 자율운항선이 규제 대상 현실로 진입했다. 4단계 자율 등급 체계가 정립됐다.","eSum":"The IMO adopted the MASS Code, making autonomy a regulated reality with a four-level autonomy framework.","kImp":"자율운항 클래스·검사체계 정립 가속.","eImp":"Accelerates autonomy class and survey frameworks.","url":"https://gcaptain.com/imo-adopts-mass-code-the-autonomous-ship-moves-from-drawing-board-to-regulated-reality/"},{"code":"DIG-10","title":"적대적 바다 — AI와 진화하는 해양 사이버 위협","src":"MarineLink","date":"2026","kSum":"AI가 해양 사이버 위협을 빠르게 진화시키며 전통적 보안 대응 시간 창이 붕괴되고 있다. 능동적 방어 체계가 요구된다.","eSum":"AI is rapidly evolving the maritime cyber threat, collapsing the traditional response window and demanding proactive defence.","kImp":"위협 진화 속도에 맞춘 능동적 방어 필요.","eImp":"Proactive defence must match the threat's pace.","url":"https://www.marinelink.com/news/adversarial-seas-ai-evolving-cyber-threat-513526"}]},{"code":"TECH","kTitle":"Section 8. Ship Manager Technical Team (10건)","eTitle":"Section 8. Ship Manager Technical Team (10 items)","type":"news","items":[{"code":"TECH-1","title":"Techcross HYCHLOR 2.0 BWMS, USCG 형식승인 획득","src":"MarineLink","date":"2026","kSum":"Techcross의 HYCHLOR 2.0 평형수처리장치(BWMS)가 미국 해안경비대(USCG) 형식승인을 받았다. 미국 항로 운항 선박의 BWMS 선택지가 넓어졌다.","eSum":"Techcross's HYCHLOR 2.0 ballast water management system earned USCG Type Approval, expanding BWMS options for vessels trading to the US.","kImp":"USCG 승인 BWMS 확대로 미주 운항 대응 용이.","eImp":"More USCG-approved BWMS eases US-trade compliance.","url":"https://www.marinelink.com/news/techcross-hychlor-bwms-earns-uscg-type-511661"},{"code":"TECH-2","title":"레트로핏 BWMS용 기관실 솔루션 성공 사례","src":"Hellenic Shipping News","date":"2026","kSum":"기존선 BWMS 레트로핏에 기관실(E/R) 솔루션을 적용한 성공 사례가 보고됐다. 공간 제약이 큰 노후선의 환경설비 설치 난제를 해소한다.","eSum":"A successful engine-room solution for BWMS retrofit was reported, addressing the challenge of installing environmental equipment on space-constrained older ships.","kImp":"노후선 BWMS 설치 공간 문제 해법 제시.","eImp":"Offers a solution to BWMS space constraints on older ships.","url":"https://www.hellenicshippingnews.com/successful-e-r-solution-for-bwms-on-retrofit/"},{"code":"TECH-3","title":"스크러버 레트로핏, 모듈식으로 입거기간 단축","src":"Marine Insight","date":"2026","kSum":"신규 모듈식 스크러버 레트로핏 방식이 통상 2주 이상이던 입거 기간을 수일로 단축한다. 대형선은 거래 패턴·경쟁 요율로 극동 야드를 선호한다.","eSum":"A new modular scrubber-retrofit approach cuts dock time from two-plus weeks to a few days; large vessels favour Far East yards for trading patterns and rates.","kImp":"입거기간 단축으로 레트로핏 기회비용 절감.","eImp":"Shorter dock time lowers retrofit opportunity cost.","url":"https://www.marineinsight.com/scrubber-system-on-ship/"},{"code":"TECH-4","title":"선박 레트로핏 리스크 관리 — 설계·실행·검증","src":"Hellenic Shipping News","date":"2026","kSum":"선박 레트로핏 리스크를 줄이기 위해 설계·실행·검증 3단계 접근이 강조됐다. 사전 엔지니어링과 검증이 공기·비용 초과를 막는 핵심이다.","eSum":"A three-step design, execution and verification approach is emphasized to de-risk ship retrofits, with upfront engineering and verification key to avoiding schedule and cost overruns.","kImp":"레트로핏 사전 엔지니어링이 리스크 관리의 핵심.","eImp":"Upfront engineering is central to retrofit risk management.","url":"https://www.hellenicshippingnews.com/how-to-derisk-ship-retrofits-design-execution-and-verification/"},{"code":"TECH-5","title":"BWM 레트로핏 7단계 가이드","src":"SAFETY4SEA","date":"2026","kSum":"SAFETY4SEA가 평형수처리장치(BWM) 레트로핏을 위한 7단계 가이드를 제시했다. 사전조사·설계·설치·시운전 절차의 체계화를 권고한다.","eSum":"SAFETY4SEA outlined a seven-step guide for BWM retrofits, recommending a structured process across survey, design, installation and commissioning.","kImp":"표준화된 절차로 레트로핏 품질·일정 관리.","eImp":"Standardized steps improve retrofit quality and scheduling.","url":"https://safety4sea.com/7-steps-bwm-retrofits/"},{"code":"TECH-6","title":"레트로핏 수요 폭증에 수리조선소 만선","src":"Hellenic Shipping News","date":"2026","kSum":"환경규제 대응 레트로핏 수요가 급증하며 수리조선소가 일감으로 가득 찼다. BWMS·스크러버·이중연료 개조 수요가 도크 가용성을 압박한다.","eSum":"Surging compliance-driven retrofit demand has filled ship repair yards, with BWMS, scrubber and dual-fuel conversion work squeezing dock availability.","kImp":"도크 슬롯 확보 경쟁 심화 — 사전 계획 필수.","eImp":"Competition for dock slots intensifies — plan ahead.","url":"https://www.hellenicshippingnews.com/ship-repair-yards-fill-up-on-retrofitting-rush/"},{"code":"TECH-7","title":"PMS에 반드시 포함할 20가지 항목","src":"Marine Insight","date":"2026","kSum":"계획정비체계(PMS)에 포함해야 할 20가지 핵심 항목이 정리됐다. 운전시간(4000/8000hr) 및 캘린더 주기 기반 정비 관리가 강조된다.","eSum":"Twenty essential items to include in a Planned Maintenance System were outlined, emphasizing running-hour (4000/8000 hr) and calendar-based maintenance management.","kImp":"PMS 표준화로 기관 신뢰성·검사 대비 강화.","eImp":"PMS standardization boosts machinery reliability and survey readiness.","url":"https://www.marineinsight.com/guidelines/20-things-that-should-be-included-in-the-planned-maintenance-system/"},{"code":"TECH-8","title":"선박 입거(드라이도크) 종합 가이드","src":"Marine Insight","date":"2026","kSum":"SOLAS상 모든 상선은 5년 내 2회 입거 선체검사가 요구되며 36개월 이내 중간검사가 필요하다. Graving dock가 레트로핏·개조에 유리하다.","eSum":"Under SOLAS, all merchant vessels require two dry-dock hull surveys within five years plus an intermediate survey within 36 months; graving docks are advantageous for retrofits.","kImp":"입거 일정·검사주기 통합 관리로 비용 최적화.","eImp":"Integrated dry-dock and survey scheduling optimizes cost.","url":"https://www.marineinsight.com/guidelines/dry-dock-types-of-dry-docks-requirements-for-dry-dock/"},{"code":"TECH-9","title":"선박 스크러버 시스템 가이드","src":"Marine Insight","date":"2026","kSum":"하이브리드 스크러버는 개방형·폐쇄형 운전이 모두 가능하다. 외해에서는 개방형, ECA·항만에서는 폐쇄형으로 운전해 배출규제에 대응한다.","eSum":"Hybrid scrubbers can run open- and closed-loop — open loop at sea and closed loop in ECA zones and ports — to meet emission rules.","kImp":"운항해역별 스크러버 운전모드 관리 중요.","eImp":"Managing scrubber modes by sea area is important for compliance.","url":"https://www.marineinsight.com/scrubber-system-on-ship/"},{"code":"TECH-10","title":"선상 정비작업 수행 방법","src":"Marine Insight","date":"2026","kSum":"선상 정비작업의 계획·실행·기록 절차가 정리됐다. 운전시간·상태기반 정비와 안전작업허가(PTW) 체계의 연계가 강조된다.","eSum":"Onboard maintenance planning, execution and recording were outlined, emphasizing the link between running-hour/condition-based maintenance and the permit-to-work system.","kImp":"PTW 연계 정비로 안전·신뢰성 동시 확보.","eImp":"PTW-linked maintenance secures both safety and reliability.","url":"https://www.marineinsight.com/guidelines/how-maintenance-work-is-done-onboard-a-ship/"}]},{"code":"HR","kTitle":"Section 9. Marine HR (10건)","eTitle":"Section 9. Marine HR (10 items)","type":"news","items":[{"code":"HR-1","title":"해양인재 육성 프로그램 — 승무원 위기 대응","src":"SAFETY4SEA","date":"2026","kSum":"STCW 요건에 완전 부합하는 해양인재 육성 프로그램이 장기 전문성 개발에 초점을 두고 추진된다. 심화되는 승무원 위기에 대응한 체계적 양성을 목표로 한다.","eSum":"A Maritime Talent Development Program fully aligned with STCW focuses on long-term professional development to navigate the deepening crew crisis.","kImp":"체계적 인재양성이 인력난 완화의 핵심.","eImp":"Structured talent development is key to easing the labour crunch.","url":"https://safety4sea.com/cm-maritime-talent-development-program-navigating-the-crew-crisis/"},{"code":"HR-2","title":"선원 임금 상승에도 정신건강·복지 문제 지속","src":"Marine Insight","date":"2026","kSum":"선원 임금이 일부 직급에서 2023년 대비 최대 10% 상승했으나 정신건강·복지 만족도는 하락했다. 식수·식량 부족(25%), 임금 체불(35%) 등 문제가 보고됐다.","eSum":"Seafarer salaries rose up to 10% versus 2023 for some ranks, yet mental-health and welfare satisfaction fell; 25% reported lack of food/water and 35% reported late pay.","kImp":"임금 인상만으로는 복지·정신건강 개선 한계.","eImp":"Pay rises alone cannot fix welfare and mental-health gaps.","url":"https://www.marineinsight.com/seafarer-salaries-continue-to-rise-but-mental-health-welfare-issues-persist-reports/"},{"code":"HR-3","title":"MLC 20주년 — 휴식시간 위기와 선원 부족","src":"Seatrade Maritime","date":"2026","kSum":"해사노동협약(MLC) 발효 20주년을 맞아 근로·휴식시간 준수 위기와 선원 부족이 핵심 과제로 부각됐다. 피로관리와 정원확보의 균형이 시급하다.","eSum":"At MLC's 20th anniversary, hours-of-work-and-rest compliance and seafarer shortage emerged as core challenges, underscoring the urgent need to balance fatigue management and manning.","kImp":"피로관리-정원확보의 구조적 균형이 관건.","eImp":"Structural balance of fatigue management and manning is critical.","url":"https://www.seatrade-maritime.com/crewing/mlc-at-20-hours-of-work-and-rest-crisis-and-seafarer-shortage"},{"code":"HR-4","title":"해운, 잠재적 인력 위기 대응 본격화","src":"Splash 247","date":"2026","kSum":"BIMCO·ICS는 2026년까지 약 9만 명의 추가 사관이 필요하다고 전망했으며 선원 부족은 17년 만의 최고치를 기록했다. 업계가 인력 위기 대응에 나섰다.","eSum":"BIMCO and ICS projected a need for nearly 90,000 additional officers by 2026 with shortages at a 17-year high, prompting the industry to tackle the workforce crisis.","kImp":"사관 인력 부족이 구조적 리스크로 고착.","eImp":"Officer shortages entrenching as a structural risk.","url":"https://splash247.com/shipping-tackles-potential-workforce-crisis/"},{"code":"HR-5","title":"IMO, 선원 피로·근로/휴식시간·괴롭힘 정조준","src":"IMO","date":"2026","kSum":"IMO가 선원 피로, 근로·휴식시간, 해상 괴롭힘 문제를 정조준한 정책 브리핑을 냈다. STCW 개정과 연계해 인적요인 관리 강화가 추진된다.","eSum":"The IMO issued a briefing targeting seafarer fatigue, work/rest hours and harassment at sea, advancing human-factors management alongside STCW amendments.","kImp":"피로·인적요인 관리가 안전·인사의 핵심 의제.","eImp":"Fatigue and human factors are central safety/HR agendas.","url":"https://www.imo.org/en/mediacentre/pressbriefings/pages/seafarer-fatigue-work-hours-harassment.aspx"},{"code":"HR-6","title":"선원 행복도 하락 — 근로·생활여건 악화","src":"Marine Insight","date":"2026","kSum":"선원 행복도가 근로·생활여건 악화로 하락했다. 정신건강 지원 유용성 평가가 2023년 75%에서 65%로 떨어졌고 괴롭힘 경험이 25%에 달했다.","eSum":"Seafarers' happiness declined as working and living conditions worsened; usefulness of mental-health support fell from 75% (2023) to 65%, and 25% reported harassment.","kImp":"복지·정신건강 투자 실효성 제고 필요.","eImp":"Need to improve the effectiveness of welfare/mental-health support.","url":"https://www.marineinsight.com/shipping-news/seafarers-happiness-declines-as-working-and-living-conditions-worsen-at-sea/"},{"code":"HR-7","title":"3분기 선원 행복지수 전반적 급락","src":"Seatrade Maritime","date":"2026","kSum":"분기 선원 행복지수(Seafarers Happiness Index)가 전 항목에서 급락했다. 임금 정체와 업무 부담 가중에 대한 불만이 반영됐다.","eSum":"The quarterly Seafarers Happiness Index plunged across the board, reflecting frustration with stagnant wages and rising workload.","kImp":"행복지수 악화가 이탈·인력난을 가속할 위험.","eImp":"Falling happiness risks accelerating attrition and shortages.","url":"https://www.seatrade-maritime.com/crewing/seafarer-happiness-plunges-across-the-board-in-q3"},{"code":"HR-8","title":"IMO, 선원 지원 자원·정보 제공","src":"IMO","date":"2026","kSum":"IMO가 선원 지원을 위한 자원·정보를 종합 안내했다. 위기·유기(abandonment) 상황의 선원 보호와 복지 지원 체계를 강조한다.","eSum":"The IMO compiled resources and information for supporting seafarers, emphasizing protection and welfare support in crisis and abandonment situations.","kImp":"선원 유기·위기 대응의 제도적 안전망 강화.","eImp":"Strengthens the institutional safety net for crisis and abandonment.","url":"https://www.imo.org/en/mediacentre/hottopics/pages/supporting-seafarers.aspx"},{"code":"HR-9","title":"'선원의 날'을 넘어 — 지속적 처우 개선 과제","src":"Marine Insight","date":"2026","kSum":"'선원의 날(Day of the Seafarer)'을 계기로 일회성 행사를 넘어선 지속적 처우 개선 필요성이 제기됐다. 핵심노동자로서의 인정과 실질적 복지 강화가 요구된다.","eSum":"Marking the Day of the Seafarer, calls grew for sustained welfare improvement beyond one-off events, with recognition as key workers and tangible support needed.","kImp":"상시적 처우 개선 체계 구축이 과제.","eImp":"Building a continuous welfare-improvement framework is the task.","url":"https://www.marineinsight.com/maritime-law/one-day-for-seafarers-a-lifetime-of-work-ahead/"},{"code":"HR-10","title":"STCW 개정 — 폭력·괴롭힘 예방 교육 의무화 발효","src":"SAFETY4SEA","date":"2026-01-01","kSum":"2026년 1월 1일부로 STCW 코드 개정에 따라 전 선원 대상 해상 폭력·괴롭힘 예방·대응 교육이 의무화됐다. 여성 선원의 괴롭힘 경험률이 50%를 상회하는 현실을 반영했다.","eSum":"From January 1, 2026, amendments to the STCW Code mandate training for all seafarers on preventing and responding to violence and harassment at sea, reflecting that over 50% of female seafarers report harassment.","kImp":"폭력·괴롭힘 예방 교육이 승선 전 필수요건화.","eImp":"Anti-harassment training becomes a pre-boarding requirement.","url":"https://safety4sea.com/cm-maritime-talent-development-program-navigating-the-crew-crisis/"}]},{"code":"HSEQ","kTitle":"Section 10. HSEQ (Health · Safety · Environment · Quality, 10건)","eTitle":"Section 10. HSEQ (Health · Safety · Environment · Quality, 10 items)","type":"news","items":[{"code":"HSEQ-1","title":"North P&I Club, 손실예방 25년 노하우 강화","src":"SAFETY4SEA","date":"2026","kSum":"North P&I Club이 25년간 축적한 손실예방(loss prevention) 노하우를 바탕으로 회원사 사고·클레임 감축 지원을 강화한다고 밝혔다. 데이터 기반 예방 활동을 확대한다.","eSum":"The North P&I Club reaffirmed its commitment to loss prevention built on 25 years of helping members reduce accidents and claims, expanding data-driven prevention.","kImp":"P&I 손실예방 프로그램이 안전관리 보강 수단.","eImp":"P&I loss-prevention programs reinforce safety management.","url":"https://safety4sea.com/north-p-i-club-commits-to-loss-prevention/"},{"code":"HSEQ-2","title":"해양 인텔리전스로 강화되는 P&I 리스크 관리","src":"Hellenic Shipping News","date":"2026","kSum":"해양 인텔리전스가 P&I 클럽의 리스크 관리를 강화하고 있다. 풀 진입 리스크 사전 파악과 객관적 증거 기반 클레임 처리가 핵심으로 부상했다.","eSum":"Maritime intelligence is strengthening P&I club risk management, enabling earlier identification of pool risk and evidence-based claims resolution.","kImp":"데이터 기반 리스크 평가가 보험·안전관리에 확산.","eImp":"Data-driven risk assessment spreads across insurance and safety.","url":"https://www.hellenicshippingnews.com/how-maritime-intelligence-is-strengthening-pi-club-risk-management/"},{"code":"HSEQ-3","title":"DNV, EU 규정 현장점검 절차 안내 — 2026 FuelEU 검증 대비","src":"SAFETY4SEA","date":"2026","kSum":"DNV가 EU 규정(2023/2917, 2024/2027)에 따른 현장점검 절차와 컴플라이언스 책임을 안내했다. 2026년 첫 FuelEU 검증(3/31 마감) 전 조기 점검을 권고했다.","eSum":"DNV issued guidance on EU site-visit procedures and compliance duties, recommending early visits ahead of the first FuelEU verification (deadline March 31, 2026).","kImp":"FuelEU 첫 검증 대비 조기 현장점검 필요.","eImp":"Schedule early site visits ahead of first FuelEU verification.","url":"https://safety4sea.com/dnv-key-steps-for-site-visit-procedures-under-eu-regulations/"},{"code":"HSEQ-4","title":"FuelEU Maritime 규정 — 핵심 해설","src":"SAFETY4SEA","date":"2026","kSum":"FuelEU Maritime 규정의 적용범위와 준수 메커니즘이 해설됐다. 연료 온실가스 집약도의 단계적 감축과 풀링·페널티 구조 이해가 필수다.","eSum":"The FuelEU Maritime regulation's scope and compliance mechanisms were explained, stressing the need to understand the gradual GHG-intensity reduction and pooling/penalty structure.","kImp":"연료 GHG 집약도 관리가 운항 의사결정에 직결.","eImp":"Managing fuel GHG intensity directly affects operating decisions.","url":"https://safety4sea.com/cm-fueleu-maritime-regulation-and-insights/"},{"code":"HSEQ-5","title":"국제안전관리(ISM) 코드 — 안전관리체계의 근간","src":"IMO","date":"2026","kSum":"ISM 코드는 선박 안전운항·오염방지의 국제표준으로 모든 선박에 적용되며 안전관리체계(SMS)로 뒷받침된다. 내·외부 심사를 통한 SMS 부적합 관리가 핵심이다.","eSum":"The ISM Code is the international standard for safe ship operation and pollution prevention, applied to all ships and supported by a Safety Management System managed through internal and external audits.","kImp":"SMS 실효성 점검이 HSEQ 관리의 출발점.","eImp":"Verifying SMS effectiveness is the starting point of HSEQ management.","url":"https://www.imo.org/en/ourwork/humanelement/pages/ismcode.aspx"},{"code":"HSEQ-6","title":"선박 안전관리체계(SMS)란 무엇인가","src":"Marine Insight","date":"2026","kSum":"SMS는 모든 선박이 의무 안전규정과 IMO·선급 기준을 준수하도록 보장하는 체계다. 절차서·비상대응·기록관리의 통합 운영이 요구된다.","eSum":"A Safety Management System ensures every ship complies with mandatory safety rules and IMO/class standards, requiring integrated procedures, emergency response and record-keeping.","kImp":"문서화-실행-기록의 일관성이 SMS 신뢰성 좌우.","eImp":"Consistency of documentation, execution and records drives SMS credibility.","url":"https://www.marineinsight.com/marine-safety/what-is-safety-management-system-sms-on-ships/"},{"code":"HSEQ-7","title":"IMO 공식안전평가(FSA) 방법론","src":"IMO","date":"2026","kSum":"공식안전평가(FSA)는 위험식별·평가·통제·비용편익 분석을 통해 규제 의사결정을 지원하는 구조적 방법론이다. 리스크 기반 안전관리의 토대가 된다.","eSum":"Formal Safety Assessment is a structured methodology supporting regulatory decision-making through hazard identification, risk assessment, control and cost-benefit analysis — the basis of risk-based safety management.","kImp":"리스크 기반 접근이 HSEQ 정책 수립의 표준.","eImp":"Risk-based approach is the standard for HSEQ policymaking.","url":"https://www.imo.org/en/ourwork/safety/pages/formalsafetyassessment.aspx"},{"code":"HSEQ-8","title":"Skuld P&I, 화물잔류물 처리 손실예방 안내 (MARPOL Annex V)","src":"SAFETY4SEA","date":"2026","kSum":"Skuld P&I Club이 MARPOL Annex V에 따른 화물잔류물(cargo residues) 처리 손실예방 지침을 발표했다. 부적절한 폐기로 인한 환경위반·벌금 리스크 예방이 목적이다.","eSum":"The Skuld P&I Club issued loss-prevention guidance on disposal of cargo residues in line with MARPOL Annex V, aimed at preventing environmental violations and fines from improper disposal.","kImp":"화물잔류물 관리로 환경 컴플라이언스 리스크 저감.","eImp":"Proper cargo-residue handling reduces environmental compliance risk.","url":"https://safety4sea.com/disposal-of-cargo-residues/"},{"code":"HSEQ-9","title":"OceanScore·Anglo-Eastern, EU ETS·FuelEU 컴플라이언스 협력","src":"Hellenic Shipping News","date":"2026","kSum":"OceanScore와 Anglo-Eastern이 EU ETS·FuelEU Maritime 컴플라이언스 지원을 위해 협력한다. 배출권 관리·연료 GHG 집약도 보고를 지원한다.","eSum":"OceanScore and Anglo-Eastern are collaborating to support EU ETS and FuelEU Maritime compliance, covering allowance management and fuel GHG-intensity reporting.","kImp":"복합 EU 규제 대응을 위한 전문 지원 수요 증가.","eImp":"Rising demand for specialist support on overlapping EU rules.","url":"https://www.hellenicshippingnews.com/oceanscore-and-anglo-eastern-collaborate-on-eu-ets-and-fueleu-maritime-compliance-support/"},{"code":"HSEQ-10","title":"선사 설립에 필요한 ISM 증서","src":"Marine Insight","date":"2026","kSum":"선사 설립·운영에 필요한 ISM 관련 증서(DOC·SMC)와 요건이 정리됐다. 안전관리적합증서(DOC)와 선박안전관리증서(SMC) 유지·갱신이 운항 적격성의 기본이다.","eSum":"The ISM-related certificates (DOC and SMC) and requirements for establishing a shipping company were outlined, with maintaining the Document of Compliance and Safety Management Certificate fundamental to operating eligibility.","kImp":"DOC·SMC 유지가 운항 적격성의 기본 요건.","eImp":"Maintaining DOC/SMC is fundamental to operating eligibility.","url":"https://www.marineinsight.com/marine-safety/what-ism-certificates-you-require-to-start-a-shipping-company/"}]},{"code":"KR","kTitle":"Section 11. 한국해운 시장 (Korean Shipping Market, 10건)","eTitle":"Section 11. Korean Shipping Market (10 items)","type":"news","items":[{"code":"KR-1","title":"HD현대(HD Hyundai), MSR 추진 PCTC 개념승인 (6/5, Posidonia)","src":"Hellenic Shipping News","date":"2026-06-05","kSum":"HD현대중공업·HD한국조선해양·현대글로비스(Hyundai Glovis)·한국원자력연구원 등이 용융염원자로(MSR) 적용 대형 PCTC 개념설계로 6월 5일 Posidonia에서 Lloyd's Register 기본인증(AiP)을 받았다.","eSum":"HD Hyundai Heavy Industries, HD KSOE, Hyundai Glovis and KAERI received Lloyd's Register Approval in Principle at Posidonia (June 5) for a molten-salt-reactor (MSR) powered large PCTC.","kImp":"한국, 원자력 추진 상선 선도 — 무탄소 차세대 경쟁.","eImp":"Korea leads nuclear-propelled merchant concepts in the zero-carbon race.","url":"https://www.hellenicshippingnews.com/hd-hyundai-expands-smr-powerd-ships-to-car-carriers/"},{"code":"KR-2","title":"HD현대(HD Hyundai), HMM 발주 확정 — 18년 만 최대 컨선 수주","src":"Maritime Executive","date":"2026","kSum":"HD현대가 HMM 컨테이너선 발주를 확정하며 18년 만 최대 수주 실적을 기록했다. HMM 총 발주는 약 28억 달러로 HD현대·한화오션에 분산됐다.","eSum":"HD Hyundai confirmed an HMM order, its highest containership intake in 18 years; HMM's ~US$2.8bn deal is split between HD Hyundai and Hanwha Ocean.","kImp":"한국 해운-조선 수직 협력 강화.","eImp":"Strengthens vertical Korea shipping-shipbuilding cooperation.","url":"https://maritime-executive.com/article/hd-hyundai-confirms-hmm-order-pushes-to-highest-boxship-orders-in-18-years"},{"code":"KR-3","title":"한화오션(Hanwha Ocean)·현대, 한국 첫 국산 구축함 수주 경쟁","src":"Maritime Executive","date":"2026","kSum":"한화오션(Hanwha Ocean)과 HD현대가 한국 최초의 국산 차기 구축함 건조를 두고 경쟁한다. 방산 수주가 조선 수익성의 새로운 축으로 부상했다.","eSum":"Hanwha Ocean and HD Hyundai will square off to build Korea's first domestic next-generation destroyer, with defense orders emerging as a new profit pillar for shipbuilding.","kImp":"방산 수주가 한국 조선 고부가 동력으로 부상.","eImp":"Defense orders become a high-value driver for Korean yards.","url":"https://maritime-executive.com/article/hanwha-and-hyundai-to-square-off-to-build-korea-s-first-domestic-destroyer"},{"code":"KR-4","title":"삼성중공업(SHI), 한화오션에 선박 블록 공급 계약","src":"Maritime Executive","date":"2026","kSum":"삼성중공업(Samsung Heavy Industries)이 한화오션(Hanwha Ocean)에 선박 건조용 블록을 공급하는 계약을 체결했다. 한국 조선사 간 분업·협업이 확대되고 있다.","eSum":"Samsung Heavy Industries contracted Hanwha Ocean to provide blocks for shipbuilding projects, reflecting growing inter-yard division of work in Korea.","kImp":"수주잔량 폭증 속 야드 간 협업 확대.","eImp":"Yard-to-yard collaboration grows amid record backlogs.","url":"https://maritime-executive.com/article/shi-contracts-hanwha-ocean-to-provide-blocks-for-shipbuilding-projects"},{"code":"KR-5","title":"中, HMM-현대글로비스(Hyundai Glovis) 최대 자동차선 진수","src":"Maritime Executive","date":"2026","kSum":"중국 조선소가 HMM-현대글로비스(Hyundai Glovis) 협력 사업의 최대 규모 자동차운반선을 진수했다. HMM 다각화 전략의 첫 자동차선으로 현대글로비스가 운영한다.","eSum":"A Chinese yard launched the largest car carrier for the HMM-Hyundai Glovis partnership — HMM's first vehicle carrier under its diversification strategy, to be operated by Hyundai Glovis.","kImp":"한국 선사 자동차물류 경쟁력 강화.","eImp":"Strengthens Korean carriers' vehicle-logistics competitiveness.","url":"https://maritime-executive.com/article/china-launches-largest-car-carrier-for-hmm-hyundai-glovis-partnership"},{"code":"KR-6","title":"신조 추진 HMM, 中 조선소 검토 논란","src":"한국해운신문 (Korea Maritime Press)","date":"2026","kSum":"HMM이 1만 TEU급 컨선 16척을 2027~2028년 인도 조건으로 신조 추진 중이나, 한국 대비 척당 최소 2천만 달러 저렴한 중국 조선소를 유력 후보로 검토해 논란이 일고 있다.","eSum":"HMM is pursuing 16 boxships (~10,000 TEU) for 2027-2028, but is reportedly considering Chinese yards (at least US$20m cheaper per ship), sparking controversy.","kImp":"자국 조선 활용 vs 선가 경쟁력 정책 딜레마.","eImp":"Policy dilemma: support domestic yards vs price competitiveness.","url":"http://www.maritimepress.co.kr/news/articleView.html?idxno=321651"},{"code":"KR-7","title":"HMM, 본점 부산 변경 최종 확정","src":"코리아쉬핑가제트 (KSG)","date":"2026-05-08","kSum":"HMM이 5월 8일 임시주총에서 본사 소재지 정관을 변경해 부산 이전을 확정했다. 북항 내 랜드마크 사옥 건립도 추진한다.","eSum":"At a May 8 EGM, HMM amended its articles to relocate headquarters to Busan, planning a landmark Bukhang HQ building.","kImp":"해운 거점 부산 집중화 정책의 상징적 진전.","eImp":"Symbolic progress in concentrating shipping in Busan.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147161"},{"code":"KR-8","title":"해양수산부(MOF) 2026년 예산 7조3,287억 원 편성","src":"해양수산부 (MOF)","date":"2026","kSum":"해양수산부(MOF)가 2026년 예산을 전년比 8.1% 증가한 7조3,287억 원으로 편성했다. 부산항 진해신항 예산을 4,622억 원으로 증액했다.","eSum":"Korea's MOF set its 2026 budget at KRW 7.33 trillion (+8.1%), raising Busan Jinhae New Port funding to KRW 462.2bn.","kImp":"항만·해양산업 인프라 투자 확대 기조.","eImp":"Continued expansion of port and maritime infrastructure investment.","url":"https://www.mof.go.kr/index.do?menuSeq=1074"},{"code":"KR-9","title":"한국 조선, LNG·방산 수주로 3.5년치 일감 확보","src":"Hellenic Shipping News","date":"2026","kSum":"한국 조선소들이 LNG·방산 수주에 힘입어 3.5년치 수주잔량을 확보하고 선가를 끌어올렸다. 2026년 신규 수주의 33%를 LNG선이 주도할 전망이다.","eSum":"Korean shipbuilders secured a 3.5-year backlog as LNG and defense orders lifted prices; LNG carriers are expected to lead 33% of 2026 new orders.","kImp":"풍부한 수주잔량이 선가·수익성 지지.","eImp":"Ample backlog supports prices and profitability.","url":"https://www.hellenicshippingnews.com/korean-shipbuilders-secure-3-5-year-backlog-as-lng-and-defense-orders-lift-prices/"},{"code":"KR-10","title":"한화오션(Hanwha Ocean), LNG선 200척째 인도 — 업계 최초","src":"TradeWinds","date":"2026","kSum":"한화오션(Hanwha Ocean)이 업계 최초로 LNG 운반선 200척째 인도를 달성했다. LNG선 건조 분야 한국의 누적 실적과 기술력을 입증했다.","eSum":"Hanwha Ocean claimed an industry first with delivery of its 200th LNG carrier, validating Korea's track record and leadership in LNG carrier construction.","kImp":"LNG선 건조 누적 실적 세계 선두 입지 확인.","eImp":"Confirms global leadership in cumulative LNG carrier construction.","url":"https://www.tradewindsnews.com/gas/hanwha-ocean-claims-shipbuilding-first-with-delivery-of-its-200th-lng-carrier/2-1-1782257"}]},{"code":"INS","kTitle":"Section 12. P&I·H&M 보험 (10건)","eTitle":"Section 12. P&I / H&M Insurance (10 items)","type":"news","items":[{"code":"INS-1","title":"Gard, 페르시아만 전쟁위험 담보 취소·재설정 (3/10)","src":"Gard","date":"2026-03-10","kSum":"Gard가 재보험사 통보에 따라 이란·페르시아만 전쟁위험 담보에 7일 취소예고를 발효(3/10)하고, 페르시아만·오만만·인도양·아덴만·남홍해를 고위험구역으로 새로 반영해 담보를 재설정했다.","eSum":"Following reinsurer notice, Gard issued 7 days' cancellation on Hull War policies effective March 10, 2026, reinstating cover with new high-risk areas incl. the Persian/Arabian Gulf, Gulf of Oman, Indian Ocean, Gulf of Aden and Southern Red Sea.","kImp":"전쟁위험 담보 범위·요율 변동 — 통항 전 확인 필수.","eImp":"War-risk scope and rates shifting — verify before transit.","url":"https://www.hellenicshippingnews.com/iumi-statement-marine-insurance-in-the-middle-east-region/"},{"code":"INS-2","title":"Skuld, 특정 전쟁위험 담보 취소 통보 (3/5)","src":"Skuld","date":"2026-03-05","kSum":"Skuld가 2026년 3월 5일부로 특정 전쟁위험에 대한 담보 취소를 통보했다. 중동 정세 악화에 따른 재보험 조건 변화가 배경이다.","eSum":"Skuld issued a notice of cancellation effective March 5, 2026 for certain war risks, reflecting changing reinsurance terms amid Middle East tensions.","kImp":"전쟁위험 담보 재가입·조건 점검 필요.","eImp":"Review war-risk re-cover and conditions.","url":"https://www.skuld.com/about/-/circulars/2026/general-notice-of-cancellation-in-respect-of-certain-war-risks-/"},{"code":"INS-3","title":"IUMI, 중동 해역 마린보험 성명 — 통항 안전 주시","src":"Hellenic Shipping News","date":"2026","kSum":"IUMI가 페르시아만·홍해의 안전 통항을 면밀히 주시하고 있다는 성명을 냈다. 다수 선박이 만내 발이 묶이고 고위험구역 회피 항로가 늘고 있다.","eSum":"IUMI issued a statement closely monitoring safe passage in the Persian Gulf and Red Sea, noting vessels trapped in the Gulf and growing rerouting to avoid high-risk areas.","kImp":"지정학 리스크가 보험·운임에 동시 반영.","eImp":"Geopolitical risk feeds into both insurance and freight.","url":"https://www.hellenicshippingnews.com/iumi-statement-marine-insurance-in-the-middle-east-region/"},{"code":"INS-4","title":"IUMI, 어려운 선체보험 시장·상승 리스크 경고","src":"IUMI","date":"2026","kSum":"IUMI가 선체(hull) 보험 시장의 어려움과 상승하는 리스크를 경고했다. 고령선대·중대 손해·지정학 충격·에너지전환 복잡성이 리스크 환경을 심화시키고 있다.","eSum":"IUMI warned of a challenging hull market and rising risk, as an ageing fleet, severe losses, geopolitical shocks and energy-transition complexity intensify the risk environment.","kImp":"선체보험 경색 가능성 — 선주 보험료 인상 압박.","eImp":"Possible hull-market hardening pressures owner premiums.","url":"https://www.hellenicshippingnews.com/iumi-highlights-challenging-hull-marine-insurance-market-and-elevated-risk/"},{"code":"INS-5","title":"The Swedish Club, 2026 선체·기계(H&M) 보험 약관 발표","src":"The Swedish Club","date":"2026","kSum":"The Swedish Club이 2026년 선체·기계(Hull & Machinery) 보험 약관을 발표했다. H&M 담보 조건의 연간 갱신 사항이 정리됐다.","eSum":"The Swedish Club published its 2026 Hull & Machinery insurance terms, setting out the annual update to H&M cover conditions.","kImp":"H&M 약관 갱신 — 선체보험 가입·갱신 시 조건 확인.","eImp":"Updated H&M terms — check conditions at hull renewal.","url":"https://www.swedishclub.com/news/circulars/hull-machinery-insurance-terms-2026/"},{"code":"INS-6","title":"Gard, 선체·기계(H&M) 보험과 P&I의 접점 해설","src":"Gard","date":"2026","kSum":"Gard가 P&I 클레임 담당자 관점에서 선체·기계(H&M) 보험과 P&I의 책임 접점을 해설했다. 충돌·좌초 등에서 담보 구분과 구상(求償) 처리가 핵심이다.","eSum":"Gard explained the interface between Hull & Machinery insurance and P&I from the claims handler's perspective, focusing on cover boundaries and recourse in collision/grounding cases.","kImp":"H&M-P&I 담보 구분 이해가 클레임 대응의 기본.","eImp":"Understanding the H&M-P&I split is fundamental to claims handling.","url":"https://gard.no/en/insights/the-interface-between-hull-and-machinery-insurance-and-p-and-i-from-the-p/"},{"code":"INS-7","title":"NorthStandard, 2026 연차 호실적 — 보험료 9.38억$ (+5.8%)","src":"NorthStandard","date":"2026","kSum":"NorthStandard가 2025/26 보험연도 총보험료 9.38억 달러(전년比 5.8%↑)의 견조한 실적을 발표했다. 합병 클럽의 담보력·재무건전성이 양호하다.","eSum":"NorthStandard reported total premium income of US$938m for 2025/26 (+5.8%), with the merged club showing sound capacity and finances.","kImp":"대형 합병 P&I 클럽의 안정적 성장.","eImp":"Stable growth at the merged P&I club.","url":"https://north-standard.com/insights-and-resources/resources/press-releases/northstandard-reports-strong-results-and-strategic-momentum"},{"code":"INS-8","title":"UK P&I Club Circular 03/26 — 초과전쟁위험 buy-back $125m 상향","src":"UK P&I Club","date":"2026","kSum":"UK P&I Club 이사회가 초과전쟁위험 P&I buy-back을 $100m에서 $125m로 상향하고 $1bn 오염 한도를 유지했다. CyberOwl과 선상 사이버보안 자료도 개발했다.","eSum":"The UK P&I Club board raised the Excess War P&I buy-back to $125m (from $100m), kept the $1bn pollution limit, and developed onboard cyber materials with CyberOwl.","kImp":"전쟁위험 담보 한도 확대 — 지정학 대응 강화.","eImp":"Expanded war-risk cover reflects heightened risk.","url":"https://www.ukpandi.com/news-and-resources/circulars/article/circular-03/26-update-from-the-board"},{"code":"INS-9","title":"IUMI, 전쟁위험과 화물보험 영향 웨비나","src":"IUMI","date":"2026","kSum":"IUMI가 전쟁위험이 화물보험에 미치는 영향을 다루는 웨비나를 진행했다. 중동 정세에 따른 담보·요율·항로 변화가 핵심 주제다.","eSum":"IUMI ran a webinar on war risks and what they mean for cargo insurers, addressing cover, rate and routing changes amid Middle East tensions.","kImp":"화물보험 담보·요율 변동 대비 필요.","eImp":"Prepare for shifting cargo-cover and rates.","url":"https://iumi.com/learning/webinar/war-risks-and-what-they-mean-for-cargo-insurers/"},{"code":"INS-10","title":"P&I보험 기로 — 대형 손해배상청구 증가 (Korea P&I)","src":"쉬핑뉴스넷 (Shipping News Net)","date":"2026","kSum":"대형 손해배상청구 증가로 P&I보험이 기로에 섰으며 시장 재편 가능성이 제기됐다. Korea P&I Club(한국선주상호보험)도 IG Club 제휴로 대응 기반을 넓히고 있다.","eSum":"Rising large liability claims have put P&I insurance at a crossroads with possible restructuring; the Korea P&I Club is broadening its base via IG Club cooperation.","kImp":"대형 클레임 증가 — 한국 선사 P&I 담보·보험료 주시.","eImp":"Rising claims — watch Korean owners' P&I cover and premiums.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=47102"}]}]};